insert into public.darft_project_tasks (id,code,section,title,brief,why_it_matters,priority,status,owner_answer,assistant_note,sort_order,created_at,updated_at,updated_by) values
('06f3383e-92c6-4a26-a656-dd7133090a1c'::uuid,'REAL-001','Catalogue réel','Remplacer progressivement les œuvres fictives','Constituer une première sélection de 5 à 12 œuvres réelles avec photographies exploitables, informations fiables, disponibilité et accord de publication. Ne pas supprimer les prototypes tant qu’un remplacement réel n’est pas prêt.','DARFT doit prouver son regard par des décisions réelles, pas par la quantité de fonctionnalités.','now','todo','','',10,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('2034809c-6e2c-4951-81b6-8f16381c843b'::uuid,'CUR-001','Regard DARFT','Écrire « Pourquoi DARFT l’a choisie »','Pour chaque œuvre réelle, écrire 3 à 5 phrases concrètes sur ce qui a arrêté le regard, sans jargon de galerie et sans promesse financière.','Cette justification publique peut devenir la signature éditoriale de DARFT.','now','todo','','',20,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('c4eb862f-0d9e-461a-bcd9-0af70fd29535'::uuid,'PHOTO-001','Documentation','Définir le protocole photo des œuvres','Pour chaque œuvre : vue principale, détail matière, vue de côté ou d’épaisseur si utile, dos, signature/marque, échelle ou mise en situation lorsque pertinent.','Un langage documentaire cohérent rend DARFT identifiable sans dépendre d’effets graphiques.','now','todo','','',30,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('b984c454-e4f9-4e5d-8ce0-e74ece3ea13b'::uuid,'SEL-001','Sélections dans le temps','Préparer DARFT Selection 01','Définir la première sélection datée (par exemple Automne 2026), son nombre d’œuvres, son texte d’ouverture et sa date de clôture éditoriale. Les sélections passées devront rester consultables.','Le temps transforme le goût en historique vérifiable et donne du risque aux décisions curatoriales.','now','todo','','',40,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('4ae63e9d-909a-439c-8bc7-d5657f0ddbca'::uuid,'REV-001','DARFT Review','Tester le refus utile sur de vrais dossiers','Rédiger les premiers retours avec : point remarqué, réserve éventuelle, décision et possibilité de revenir. Éviter les scores.','Même un refus doit montrer qu’une personne a réellement regardé l’œuvre.','now','todo','','',50,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('0da429d4-04dd-492b-abdc-9a3ce994bbc7'::uuid,'VOICE-001','Voix éditoriale','Réduire les maximes automatiques','Relire les pages publiques et décider quelles phrases-signatures méritent de rester. Dans les autres sections, préférer une écriture factuelle, précise et moins systématiquement aphoristique.','Trop de formules parfaites peuvent donner une impression de texte généré et affaiblir les meilleures phrases.','next','todo','','',60,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('28791993-83f1-4dea-985b-d6e795178349'::uuid,'VIS-001','Identité visuelle','Créer une grammaire documentaire DARFT','Choisir un système récurrent : numéro d’inventaire, fiche matière/dimensions, cachet ou marque de sélection, provenance, détails, date de sélection et état de disponibilité.','Le site doit devenir reconnaissable sans logo, au-delà du style galerie crème + serif.','next','todo','','',70,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('55c51e95-e0fd-45d9-b7a2-0a9fc3336baa'::uuid,'ACQ-001','Acquisition','Définir le parcours « Demander l’œuvre »','Décider ce qu’il se passe après une demande : réponse, réservation, paiement/acompte, contrat, transport, certificat et suivi.','La vente doit ressembler à une acquisition accompagnée plutôt qu’à un panier e-commerce.','next','todo','','',80,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('474f8b8a-71f1-4204-84c6-718c4b9c4827'::uuid,'PROV-001','Provenance','Définir le dossier d’œuvre DARFT','Lister les documents remis à l’acquéreur : certificat, facture, provenance, fiche artiste, histoire de sélection, photos d’état, transport et historique utile.','La documentation et la transmission font partie du produit collection.','next','todo','','',90,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('c4f9ed8f-c623-4122-a5b7-7d247030768d'::uuid,'COM-001','Comité','Former les premiers regards humains','Identifier jusqu’à trois personnes ou profils complémentaires : art contemporain, matière/fabrication, collectionneur/espace réel. Définir comment une conviction minoritaire peut déclencher une discussion.','DARFT doit pouvoir assumer un goût humain identifiable plutôt qu’une moyenne.','next','todo','','',100,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('65604a88-0e5d-4d2f-b303-1c05c4bfcf05'::uuid,'ARCH-001','Archive invisible','Définir les règles d’archivage','Décider ce qui peut être conservé après non-sélection, avec quel consentement, quelles métadonnées, combien de temps et dans quels cas une œuvre peut réapparaître pour un collectionneur.','L’archive invisible peut devenir un actif stratégique sans gonfler le catalogue public.','next','todo','','',110,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('e5d0c71c-5dcf-4dbd-81c7-c9ef468431ce'::uuid,'MATCH-001','Archive invisible','Préparer le brief de recherche collectionneur','Créer un questionnaire simple : espace, dimensions, budget, médium, tonalité, contraintes, délai et intention. L’IA pourra assister la recherche, la proposition finale restera humaine.','Cela permet à DARFT de tirer parti d’une base plus grande que la sélection publique.','later','todo','','',120,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('0e7bd6c8-b1f3-4aa2-b805-92971509b762'::uuid,'PRIVATE-001','DARFT Private','Valider le besoin avant de développer','Ne pas construire davantage de fonctionnalités Private avant d’avoir observé des demandes réelles de recherche, d’accompagnement ou de commandes. Noter les demandes reçues et leur contexte.','Évite de sur-concevoir une activité avant d’avoir confirmé le besoin.','later','todo','','',130,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('bb742cf9-65fc-48bc-bf66-9e2000cc9a0e'::uuid,'PROJECTS-001','DARFT Projects','Valider le besoin professionnel avant de développer','Documenter les demandes éventuelles d’architectes, décorateurs, hôtels, restaurants ou entreprises avant de construire un produit dédié.','Le regard DARFT doit précéder l’offre de services.','later','todo','','',140,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('d171ed48-c3d6-47e2-beb1-7718a9999c85'::uuid,'LEGAL-001','Cadre commercial','Faire valider le cadre juridique et commercial','Préparer puis faire vérifier par un professionnel : CGV/mandat, commissions, droits de reproduction, authenticité, retours, transport, assurance, fiscalité et responsabilités.','La vente d’art et la gestion d’œuvres exigent un cadre fiable qui ne doit pas être improvisé.','next','todo','','',150,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('4f52cf5b-51f8-488a-af2e-aa88dd2a401c'::uuid,'METRIC-001','Pilotage','Choisir les métriques qui ne déforment pas le goût','Suivre des métriques opérationnelles privées : candidatures examinées, délai de réponse, demandes d’acquisition, ventes, retours collectionneurs. Éviter de transformer popularité publique et vues en critères curatoriaux.','Le pilotage business ne doit pas contaminer la sélection éditoriale.','later','todo','','',160,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('7f21f3de-dc23-4e88-a4f4-7dc2b752ab52'::uuid,'HISTORY-001','Mémoire','Documenter les décisions importantes','À chaque décision structurante, noter le pourquoi dans la doctrine ou le journal du cockpit, y compris les choix abandonnés.','Une mémoire imparfaite mais réelle rend le projet moins artificiellement lisse et facilite la reprise du travail.','now','in_progress','','',170,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null),
('48df2663-2e3a-4202-a0d0-af48ce723b36'::uuid,'LAUNCH-001','Lancement','Définir le seuil de lancement réel','Décider le minimum avant communication publique : nombre d’œuvres réelles, qualité photo, textes de sélection, parcours de demande, délais de réponse et premiers membres du comité.','Un seuil clair empêche d’accumuler des fonctions secondaires avant d’avoir un produit crédible.','now','todo','','',180,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null)
insert into public.darft_project_journal (id,title,body,kind,is_resolved,created_at,updated_at,updated_by) values
('3e43b722-fff0-4734-af07-59ebc75f8689'::uuid,'Règle de pilotage — 03 septembre 2026','DARFT doit accumuler du goût, pas des fonctionnalités. Les éléments existants ne sont pas supprimés simplement parce qu’ils sont futurs : ils restent documentés, mais le travail public est priorisé sur les œuvres réelles, le regard, la documentation et le parcours d’acquisition.','decision',false,'2026-09-03 07:23:30.638963+00'::timestamptz,'2026-09-03 07:23:30.638963+00'::timestamptz,null)
